mapper.select:
select * from ww_sys_role where 1=1

	and instr(ROLE_NAME,#{lRoleName}) > 0


	and ROLE_NAME = #{roleName}


	and instr(ROLE_ID,#{lRoleId}) > 0


	and ROLE_ID = #{roleId}


	and DEL_FLAG = #{delFlag}

mapper.update:
update ww_sys_role 
set ROLE_NAME = #{roleName,jdbcType=VARCHAR}
   ,ROLE_PID = #{rolePid,jdbcType=VARCHAR}
   ,ROLE_DESC = #{roleDesc,jdbcType=VARCHAR}
   ,DEL_FLAG = #{delFlag,jdbcType=VARCHAR}
   ,ROLE_LEVEL = #{roleLevel,jdbcType=VARCHAR}
where ROLE_ID = #{roleId}

mapper.delete:
    delete from ww_sys_role_auth_ref
	where ROLE_ID = #{roleId}
	
	and AUTH_ID = #{authId}

